    def test_register_read_context_manager(self) -> None:
        """
        Walk the register map and check every register read_fields method
        """
        reference_read_fields: dict[str, Union[bool, IntEnum, int]]
        
        # test context manager to register:
        # samplerz_axi.marker
        # build up the register value with a random base value, overlaid with
        # a random value for each field
        with self.subTest(msg='register: samplerz_axi.marker'):
            rand_reg_value = random.randrange(0, 0xFFFFFFFF + 1)
                
                    
                        
            rand_field_value = random.randrange(0, 0xFFFFFFFF + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0x0) | (rand_field_value << 0)
                        
                    
                
            
            with patch(base_name + '.write_addr_space') as write_callback_mock, \
                 patch(base_name + '.read_addr_space', return_value=rand_reg_value) as read_callback_mock:

                # first read the fields using the "normal" method, then compare the result to reading
                # via the context manager
                reference_read_fields = { 
                                          'data' : self.dut.marker.data.read()  # type: ignore[union-attr]
                                        }
                read_callback_mock.reset_mock()

                
                with self.dut.marker.single_read() as reg_context: # type: ignore[union-attr]
                    self.assertEqual(reference_read_fields['data'],
                                     reg_context.get_child_by_system_rdl_name('data').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    pass

                read_callback_mock.assert_called_once()
                write_callback_mock.assert_not_called()
        # test context manager to register:
        # samplerz_axi.control
        # build up the register value with a random base value, overlaid with
        # a random value for each field
        with self.subTest(msg='register: samplerz_axi.control'):
            rand_reg_value = random.randrange(0, 0xFFFFFFFF + 1)
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFFE) | (rand_field_value << 0)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFFD) | (rand_field_value << 1)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFFB) | (rand_field_value << 2)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFF7) | (rand_field_value << 3)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFEF) | (rand_field_value << 4)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFDF) | (rand_field_value << 5)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFFBF) | (rand_field_value << 6)
                        
                    
                
            
                
                    
                        
            rand_field_value = random.randrange(0, 0x1 + 1)
                        
                        
            rand_reg_value = (rand_reg_value & 0xFFFFFF7F) | (rand_field_value << 7)
                        
                    
                
            
            with patch(base_name + '.write_addr_space') as write_callback_mock, \
                 patch(base_name + '.read_addr_space', return_value=rand_reg_value) as read_callback_mock:

                # first read the fields using the "normal" method, then compare the result to reading
                # via the context manager
                reference_read_fields = { 
                                          'falcon1024' : self.dut.control.falcon1024.read(),  # type: ignore[union-attr]
                                          'done' : self.dut.control.done.read(),  # type: ignore[union-attr]
                                          'start' : self.dut.control.start.read(),  # type: ignore[union-attr]
                                          'stop' : self.dut.control.stop.read(),  # type: ignore[union-attr]
                                          'continuous' : self.dut.control.continuous.read(),  # type: ignore[union-attr]
                                          'reset' : self.dut.control.reset.read(),  # type: ignore[union-attr]
                                          'busy' : self.dut.control.busy.read(),  # type: ignore[union-attr]
                                          'rand_full' : self.dut.control.rand_full.read()  # type: ignore[union-attr]
                                        }
                read_callback_mock.reset_mock()

                
                with self.dut.control.single_read_modify_write(skip_write=True) as reg_context: # type: ignore[union-attr]
                
                    self.assertEqual(reference_read_fields['falcon1024'],
                                     reg_context.get_child_by_system_rdl_name('falcon1024').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['done'],
                                     reg_context.get_child_by_system_rdl_name('done').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['start'],
                                     reg_context.get_child_by_system_rdl_name('start').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['stop'],
                                     reg_context.get_child_by_system_rdl_name('stop').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['continuous'],
                                     reg_context.get_child_by_system_rdl_name('continuous').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['reset'],
                                     reg_context.get_child_by_system_rdl_name('reset').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['busy'],
                                     reg_context.get_child_by_system_rdl_name('busy').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    self.assertEqual(reference_read_fields['rand_full'],
                                     reg_context.get_child_by_system_rdl_name('rand_full').read()  # type: ignore[attr-defined,union-attr]
                                     )
                    pass

                read_callback_mock.assert_called_once()
                write_callback_mock.assert_not_called()
        # test context manager to register:
        # samplerz_axi.busy_cycles
        # build up the register value with a random base value, overlaid with
