    def test_name_map(self) -> None:
        """
        Check that the function for getting a node by its original systemRDL name works
        """
        
        
        self.assertEqual(self.dut.prng.get_child_by_system_rdl_name('seed').inst_name, 'seed')  # type: ignore[union-attr]
        
        
        
        
        self.assertEqual(self.dut.prng.get_child_by_system_rdl_name('counter').inst_name, 'counter')  # type: ignore[union-attr]
        
        
        
        
        
        self.assertEqual(self.dut.sample_histograms[0].get_child_by_system_rdl_name('histogram').inst_name, 'histogram')  # type: ignore[union-attr]
        
        
        
        
        self.assertEqual(self.dut.sample_histograms[0].get_child_by_system_rdl_name('pivot_value').inst_name, 'pivot_value')  # type: ignore[union-attr]
        
        
        
        
        self.assertEqual(self.dut.sample_histograms[0].get_child_by_system_rdl_name('pivot_index').inst_name, 'pivot_index')  # type: ignore[union-attr]
        
        
        
        
        
