class samplerz_axi_block_access(samplerz_axi_TestCase_BlockAccess): # type: ignore[valid-type,misc]
    """
    tests for all the block access methods
    """

    

    def test_register_array_context_manager(self) -> None:
        """
        Walk the register map and check that register map context managers work correctly
        """
        
        # test context manager to register:
        # samplerz_axi.prng.seed[]
        # size 4
        # total_size 44
        empty_read = [0 for i in range(44 // 4)]
        follow_along = [0 for i in range(44 // 4)]
        with self.subTest(msg='register: samplerz_axi.prng.seed[]'):
            with patch(base_name + '.write_addr_space') as write_callback_mock,\
                                patch(base_name + '.read_addr_space', return_value=0) as read_callback_mock, \
                                patch(base_name + '.read_block_addr_space',
                                      return_value=empty_read) as read_block_callback_mock , \
                                patch(base_name + '.write_block_addr_space') as write_block_callback_mock:
                with self.dut.prng.seed.single_read_modify_write() as dut:
                    pass
                
                read_callback_mock.assert_not_called()
                write_callback_mock.assert_not_called()
        # test context manager to register:
        # samplerz_axi.sample_histograms[0].histogram[]
        # size 8
        # total_size 320
        empty_read = [0 for i in range(320 // 8)]
        follow_along = [0 for i in range(320 // 8)]
        with self.subTest(msg='register: samplerz_axi.sample_histograms[0].histogram[]'):
            with patch(base_name + '.write_addr_space') as write_callback_mock,\
                                patch(base_name + '.read_addr_space', return_value=0) as read_callback_mock, \
                                patch(base_name + '.read_block_addr_space',
                                      return_value=empty_read) as read_block_callback_mock , \
                                patch(base_name + '.write_block_addr_space') as write_block_callback_mock:
                with self.dut.sample_histograms[0].histogram.single_read() as dut:
                    pass
                write_block_callback_mock.assert_not_called()
                
                read_callback_mock.assert_not_called()
                write_callback_mock.assert_not_called()
        # test context manager to register:
        # samplerz_axi.sample_histograms[1].histogram[]
        # size 8
        # total_size 320
        empty_read = [0 for i in range(320 // 8)]
        follow_along = [0 for i in range(320 // 8)]
        with self.subTest(msg='register: samplerz_axi.sample_histograms[1].histogram[]'):
            with patch(base_name + '.write_addr_space') as write_callback_mock,\
                                patch(base_name + '.read_addr_space', return_value=0) as read_callback_mock, \
                                patch(base_name + '.read_block_addr_space',
                                      return_value=empty_read) as read_block_callback_mock , \
                                patch(base_name + '.write_block_addr_space') as write_block_callback_mock:
                with self.dut.sample_histograms[1].histogram.single_read() as dut:
                    pass
                write_block_callback_mock.assert_not_called()
                
                read_callback_mock.assert_not_called()
                write_callback_mock.assert_not_called()

class samplerz_axi_alt_block_access(samplerz_axi_TestCase_AltBlockAccess): # type: ignore[valid-type,misc]
    """
    tests for all the block access methods with the alternative callbacks, this is a simpler
    version of the tests above
    """
    

    def test_register_array_context_manager(self) -> None:
        """
        Walk the register map and check that register map context managers work correctly
        """
        
        # test context manager to register with alt block interfaces:
        # samplerz_axi.prng.seed[]
        # size 4
        # total_size 44
        
        empty_read = [0 for i in range(44 // 4)]
        follow_along = [0 for i in range(44 // 4)]
        with self.subTest(msg='register: samplerz_axi.prng.seed[]'):
            with patch(base_name + '.write_addr_space') as write_callback_mock,\
                            patch(base_name + '.read_addr_space', return_value=1) as read_callback_mock, \
                            patch(base_name + '.read_block_addr_space_alt',
                                  return_value=Array('L', empty_read)) as read_block_callback_mock , \
                            patch(base_name + '.write_block_addr_space_alt') as write_block_callback_mock:
                with self.dut.prng.seed.single_read_modify_write() as dut:
                    pass
                
                read_callback_mock.assert_not_called()
                write_callback_mock.assert_not_called()
        
        # test context manager to register with alt block interfaces:
        # samplerz_axi.sample_histograms[0].histogram[]
        # size 8
        # total_size 320
        
        empty_read = [0 for i in range(320 // 8)]
        follow_along = [0 for i in range(320 // 8)]
